mapper.select:
SELECT invocation_key,owner_key,approval_key,state,version_no,expires_at,payload_digest,snapshot
FROM arte_ai_tool_approval WHERE invocation_key=#{invocation}
FOR UPDATE

mapper.update:
UPDATE arte_ai_tool_approval SET
state=#{r.state},version_no=#{r.version},payload_digest=#{r.payloadDigest},snapshot=#{r.snapshot}
WHERE invocation_key=#{r.invocationKey} AND version_no=#{expected} AND state='PENDING'

mapper.select:
SELECT invocation_key FROM arte_ai_tool_approval
WHERE state='PENDING' AND expires_at <= #{now}
ORDER BY expires_at,invocation_key LIMIT #{limit}

SELECT a.invocation_key,a.owner_key,a.approval_key,a.state,a.version_no,a.expires_at,a.payload_digest,a.snapshot
FROM arte_ai_tool_approval a JOIN arte_ai_tool_approval_audience p ON p.invocation_key=a.invocation_key
WHERE p.actor_key=#{actor}
AND a.approval_key=#{approval}
AND a.invocation_key=#{invocation}

SELECT a.invocation_key,a.owner_key,a.approval_key,a.state,a.version_no,a.expires_at,a.payload_digest,a.snapshot
FROM arte_ai_tool_approval_audience p JOIN arte_ai_tool_approval a ON a.invocation_key=p.invocation_key
WHERE p.actor_key=#{actor} AND p.pending=1 AND a.state='PENDING'
AND p.invocation_key > #{after}
ORDER BY p.invocation_key LIMIT #{limit}
